 73	function resolveStaticPath(requestPath, staticRoot) {
 74	  const rawPath = requestPath.split('?', 1)[0];
 75	  const relativePath = rawPath === '/' ? 'index.html' : rawPath;
 76	  const decodedPath = decodeURIComponent(relativePath);
 77	  const root = path.resolve(staticRoot);
 78	  const filePath = path.resolve(root, `.${path.sep}${decodedPath}`);
 79	  const relative = path.relative(root, filePath);
 80	
 81	  if (relative.startsWith('..') || path.isAbsolute(relative)) {
 82	    return null;
 83	  }
 84	  return filePath;
 85	}
