 87	async function serveStatic(requestPath, staticRoot, response) {
 88	  const filePath = resolveStaticPath(requestPath, staticRoot);
 89	  if (!filePath) {
 90	    sendText(response, 403, 'Forbidden\n');
 91	    return;
 92	  }
 93	
 94	  try {
 95	    const file = await fs.readFile(filePath);
 96	    const contentType = MIME_TYPES[path.extname(filePath).toLowerCase()] || 'application/octet-stream';
 97	    const charset = contentType === 'application/octet-stream' ? '' : '; charset=utf-8';
 98	    response.writeHead(200, {
 99	      'content-type': `${contentType}${charset}`,
100	      'content-length': file.length
101	    });
102	    response.end(file);
103	  } catch {
104	    sendText(response, 404, 'Not Found\n');
105	  }
106	}
