108	function createServer(options = {}) {
109	  const dataPath = options.dataPath || path.join(__dirname, '..', 'data', 'levels.json');
110	  const staticRoot = options.staticRoot || path.join(__dirname, '..', 'web');
111	
112	  const server = http.createServer(async (request, response) => {
113	    try {
114	      const pathname = (request.url || '/').split('?', 1)[0];
115	
116	      if (pathname.startsWith('/api/')) {
117	        if (pathname !== '/api/levels') {
118	          sendApiError(response, 404, 'API_NOT_FOUND', '未找到请求的 API。');
119	          return;
120	        }
121	        if (request.method !== 'GET') {
122	          sendApiError(response, 405, 'METHOD_NOT_ALLOWED', '该 API 不支持此请求方法。');
123	          return;
124	        }
125	
126	        const levels = await readLevels(dataPath);
127	        sendJson(response, 200, levels);
128	        return;
129	      }
130	
131	      if (!staticRoot) {
132	        sendText(response, 404, 'Not Found\n');
133	        return;
134	      }
135	      await serveStatic(pathname, staticRoot, response);
136	    } catch {
137	      sendApiError(response, 500, 'LEVEL_DATA_UNAVAILABLE', '关卡数据当前不可用，请稍后重试。');
138	    }
139	  });
140	
141	  return server;
142	}
143	
144	async function start(options = {}) {
145	  const port = Number(options.port ?? process.env.PORT ?? 3000);
146	  const server = createServer(options);
147	
148	  await new Promise((resolve, reject) => {
149	    server.once('error', reject);
150	    server.listen(port, '127.0.0.1', () => {
151	      server.off('error', reject);
152	      resolve();
153	    });
154	  });
155	
156	  const boundPort = server.address().port;
157	  return {
158	    origin: `http://127.0.0.1:${boundPort}`,
159	    port: boundPort,
160	    stop: async () => {
161	      await new Promise((resolve, reject) => {
162	        server.close((error) => {
163	          if (error) reject(error);
164	          else resolve();
165	        });
166	      });
167	    }
168	  };
169	}
170	
171	if (require.main === module) {
172	  start()
173	    .then(({ origin }) => {
174	      console.log(`Server listening at ${origin}`);
175	    })
176	    .catch((error) => {
177	      console.error(error);
178	      process.exitCode = 1;
179	    });
180	}
181	
182	module.exports = { createServer, start };

