  8	
  9	const LEVEL_DIFFICULTIES = new Set(['简单', '普通', '困难']);
 10	
 11	function createDocument() {
 12	  const loading = {
 13	    tagName: 'DIV',
 14	    id: 'loading',
 15	    textContent: '',
 16	    hidden: false,
 17	  };
 18	  const levelList = {
 19	    tagName: 'UL',
 20	    id: 'level-list',
 21	    children: [],
 22	    appendChild(child) {
 23	      this.children.push(child);
 24	    }
 25	  };
 26	  const errorMessage = {
 27	    tagName: 'DIV',
 28	    id: 'error-message',
 29	    textContent: '',
 30	    hidden: false
 31	  };
 32	  const elements = new Map([
 33	    ['loading', loading],
 34	    ['level-list', levelList],
 35	    ['error-message', errorMessage]
 36	  ]);
 37	
 38	  return {
 39	    getElementById(id) {
 40	      return elements.get(id) || null;
 41	    },
 42	    createElement(tagName) {
 43	      return {
 44	        tagName: tagName.toUpperCase(),
 45	        textContent: '',
 46	        className: '',
 47	        disabled: false,
 48	        children: [],
 49	        appendChild(child) {
 50	          this.children.push(child);
 51	        }
 52	      };
 53	    },
 54	    __elements: { loading, levelList, errorMessage }
 55	  };
 56	}
 57	
 58	function jsonResponse(body, status = 200) {
 59	  return { ok: status >= 200 && status < 300, status, json: async () => body };
 60	}
 61	
 62	function validLevels() {
 63	  return [
 64	    { id: 'opening', name: '波之国突围', difficulty: '简单', unlocked: true },
 65	    { id: 'defense', name: '木叶保卫战', difficulty: '普通', unlocked: true },
 66	    { id: 'exam', name: '中忍考试', difficulty: '困难', unlocked: false },
 67	    { id: 'pursuit', name: '晓之追击', difficulty: '困难', unlocked: false },
 68	    { id: 'valley', name: '终末之谷', difficulty: '困难', unlocked: false }
 69	  ];
 70	}
 71	
 72	describe('initLevelSelect rendering', () => {
 73	  it('shows loading first, then renders five levels and makes locked levels unselectable', async () => {
 74	    const document = createDocument();
 75	    let resolveFetch;
 76	    const fetchImpl = () => new Promise((resolve) => {
 77	      resolveFetch = () => resolve(jsonResponse(validLevels()));
 78	    });
