 82	    assert.equal(document.__elements.errorMessage.textContent, '');
 83	    assert.equal(document.__elements.levelList.children.length, 0);
 84	
 85	    resolveFetch();
 86	    await initialized;
 87	
 88	    const items = document.__elements.levelList.children;
 89	    assert.equal(document.__elements.loading.hidden, true);
 90	    assert.equal(document.__elements.errorMessage.hidden, false);
 91	    assert.equal(document.__elements.errorMessage.textContent, '');
 92	    assert.equal(items.length, 5);
 93	    validLevels().forEach((level, index) => {
 94	      const item = items[index];
