 96	      assert.equal(item.className.includes('locked'), !level.unlocked);
 97	      assert.equal(item.children.length, 1);
 98	      assert.equal(item.children[0].tagName, 'BUTTON');
 99	      assert.equal(item.children[0].type, 'button');
100	      assert.equal(item.children[0].textContent.includes(level.name), true);
101	      assert.equal(item.children[0].textContent.includes(level.difficulty), true);
