112	      requestedUrls.push(url);
113	      return jsonResponse(validLevels());
114	    };
115	    const previousDocument = global.document;
116	    const previousFetch = global.fetch;
117	    const modulePath = require.resolve('../../web/level-select');
118	    delete require.cache[modulePath];
119	
120	    global.document = document;
121	    global.fetch = fetchImpl;
